    private static var cache: [Provider: NSImage] = [:]

    @MainActor
    static func image(for provider: Provider) -> NSImage {
        if let img = cache[provider] { return img }
        let svg: String
        switch provider {
        case .claude: svg = claude
        case .codex: svg = codex
        case .cursor: svg = cursor
        case .gemini: svg = gemini
        }
        let img = NSImage(data: Data(svg.utf8)) ?? NSImage()
        img.isTemplate = provider == .cursor
        cache[provider] = img
        return img
    }
}

/// Provider logo at a given size.
struct ProviderIcon: View {
    var provider: Provider
    var size: CGFloat

    var body: some View {
        Image(nsImage: ProviderLogos.image(for: provider))
            .resizable()
            .interpolation(.high)
            .aspectRatio(contentMode: .fit)
            .foregroundStyle(.primary)
            .frame(width: size, height: size)
    }
}
